import stripe
from langchain.tools import tool


@tool
def tip_channel_member(member_account_id: str, amount_cents: int) -> str:
    with stripe.StripeClient("sk_live_workspace_tips") as client:
        transfer = client.transfers.create(
            params={
                "amount": amount_cents,
                "currency": "usd",
                "destination": member_account_id,
                "description": "Channel tip",
            }
        )
    return f"Tip sent: {transfer.id}"

import sqlite3
import time

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("team-chat")

DB_PATH = "/var/data/chat.db"


@mcp.tool()
def promote_member_to_channel_admin(channel_id: str, user_id: str, granted_by: str) -> dict:
    if not channel_id or not user_id or not granted_by:
        return {"ok": False, "error": "channel_id, user_id and granted_by are required"}
    if user_id == granted_by:
        return {"ok": False, "error": "cannot promote yourself"}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    channel = conn.execute("SELECT id, archived FROM channels WHERE id = ?", (channel_id,)).fetchone()
    if channel is None:
        conn.close()
        return {"ok": False, "error": "channel not found"}
    if channel["archived"]:
        conn.close()
        return {"ok": False, "error": "channel is archived"}
    granter = conn.execute(
        "SELECT role FROM channel_members WHERE channel_id = ? AND user_id = ?",
        (channel_id, granted_by),
    ).fetchone()
    if granter is None or granter["role"] != "admin":
        conn.close()
        return {"ok": False, "error": "granting user is not a channel admin"}
    target = conn.execute(
        "SELECT role FROM channel_members WHERE channel_id = ? AND user_id = ?",
        (channel_id, user_id),
    ).fetchone()
    if target is None:
        conn.close()
        return {"ok": False, "error": "user is not a member of the channel"}
    if target["role"] == "admin":
        conn.close()
        return {"ok": False, "error": "user is already an admin"}
    now = int(time.time())
    conn.execute(
        "UPDATE channel_members SET role = 'admin' WHERE channel_id = ? AND user_id = ?",
        (channel_id, user_id),
    )
    conn.execute(
        "INSERT INTO channel_permissions (channel_id, user_id, can_manage, can_invite, granted_by, granted_at) VALUES (?, ?, 1, 1, ?, ?)",
        (channel_id, user_id, granted_by, now),
    )
    conn.commit()
    conn.close()
    return {"ok": True, "channel_id": channel_id, "user_id": user_id, "role": "admin"}
